import { supabase } from "./supabase";

// Matches paths generated by the customer-upload Edge Function:
// <uuid-v4>.<jpg|jpeg|png|webp>
export const STORAGE_PATH_RE =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(jpg|jpeg|png|webp)$/i;

export type ImageValueType = "legacy-url" | "storage-path" | "other";

export function classifyImageValue(value: string): ImageValueType {
  if (!value) return "other";
  if (/^https?:\/\//.test(value) && /\.(jpg|jpeg|png|webp)(\?|$)/i.test(value)) {
    return "legacy-url";
  }
  if (STORAGE_PATH_RE.test(value)) return "storage-path";
  return "other";
}

export type UploadResult = { path: string; token: string };

export async function uploadCustomerPhoto(file: File): Promise<UploadResult> {
  const form = new FormData();
  form.append("file", file);

  const { data, error } = await supabase.functions.invoke("customer-upload", {
    body: form,
  });

  if (error) throw new Error(error.message ?? "Upload failed");

  const path = (data as Record<string, unknown>)?.path;
  const token = (data as Record<string, unknown>)?.token;

  if (typeof path !== "string" || typeof token !== "string") {
    const msg = typeof (data as Record<string, unknown>)?.error === "string"
      ? String((data as Record<string, unknown>).error)
      : "Upload failed";
    throw new Error(msg);
  }

  return { path, token };
}
